-- ======================================================================
-- 0004_weebly_routes_trips.sql — make every scraped shape reachable
-- ======================================================================
-- Generated by gen_routes_trips.py from data/routes/*.kmz.
-- Geometry/names: cebujeepneys.weebly.com (CC BY-NC 3.0). See SOURCES.md.
--
-- /route/shape needs trips.route_id + trips.shape_id, so we add a routes
-- row and a trip (shape_id pre-linked) for each scraped code. Existing
-- routes keep their metadata (ON CONFLICT DO NOTHING).

-- Agency used by the seed (no-op if it already exists).
ON CONFLICT (agency_id) DO NOTHING;

-- 54 routes
ON CONFLICT (route_id) DO NOTHING;

ON CONFLICT (trip_id) DO NOTHING;

-- Link any existing trip that has no shape yet to its matching shape.
UPDATE trips t SET shape_id = 'shape_' || split_part(t.route_id, '_', 2)
WHERE t.shape_id IS NULL
  AND EXISTS (SELECT 1 FROM route_shapes rs
             WHERE rs.shape_id = 'shape_' || split_part(t.route_id, '_', 2));
